#include "vela_image.h"
static uint16_t le16(const uint8_t*p){return (uint16_t)p[0]|((uint16_t)p[1]<<8);}static uint32_t le32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);}static int32_t les32(const uint8_t*p){return (int32_t)le32(p);}static int sp(uint8_t c){return c==' '||c=='\t'||c=='\r'||c=='\n';}static int dg(uint8_t c){return c>='0'&&c<='9';}
static int num(const uint8_t*d,size_t n,size_t*p,uint32_t*out){while(*p<n&&sp(d[*p]))(*p)++;if(*p>=n||!dg(d[*p]))return 0;uint32_t v=0;while(*p<n&&dg(d[*p])){v=v*10u+(uint32_t)(d[(*p)++]-'0');if(v>8192)return 0;}*out=v;return 1;}
static int pb(const uint8_t*d,size_t n,VelaImageInfo*i){if(n<54||d[0]!='B'||d[1]!='M'||le32(d+14)<40)return 0;int32_t w=les32(d+18),h=les32(d+22);uint16_t b=le16(d+28);if(w<=0||h==0||le16(d+26)!=1||(b!=24&&b!=32)||le32(d+30)!=0)return 0;uint32_t ah=(uint32_t)(h<0?-h:h);if((uint32_t)w>320||ah>240)return 0;if(i){i->width=(uint32_t)w;i->height=ah;i->channels=3;}return 1;}
static int pp(const uint8_t*d,size_t n,VelaImageInfo*i,size_t*payload){if(n<3||d[0]!='P'||d[1]!='6'||!sp(d[2]))return 0;size_t p=2;uint32_t w,h,m;if(!num(d,n,&p,&w)||!num(d,n,&p,&h)||!num(d,n,&p,&m)||!w||!h||w>320||h>240||m!=255||p>=n||!sp(d[p]))return 0;if(d[p]=='\r'&&p+1<n&&d[p+1]=='\n')p+=2;else p++;size_t need=(size_t)w*h*3u;if(p>n||need>n-p)return 0;if(i){i->width=w;i->height=h;i->channels=3;}if(payload)*payload=p;return 1;}
int vela_image_probe(const uint8_t*d,size_t n,VelaImageInfo*i){return d&&(pb(d,n,i)||pp(d,n,i,0));}
int vela_image_decode_rgb24(const uint8_t*d,size_t n,uint8_t*rgb,size_t cap,VelaImageInfo*i){VelaImageInfo z;if(!d||!rgb)return 0;if(pb(d,n,&z)){size_t need=(size_t)z.width*z.height*3u;if(need>cap)return 0;uint32_t off=le32(d+10);size_t sb=(size_t)le16(d+28)/8u,row=((size_t)z.width*sb+3u)&~3u;int32_t sh=les32(d+22);if(off>n||row>(n-off)/z.height)return 0;for(uint32_t y=0;y<z.height;y++){uint32_t sy=sh>0?z.height-1u-y:y;const uint8_t*s=d+off+(size_t)sy*row;uint8_t*o=rgb+(size_t)y*z.width*3u;for(uint32_t x=0;x<z.width;x++){o[x*3]=s[x*sb+2];o[x*3+1]=s[x*sb+1];o[x*3+2]=s[x*sb];}}if(i)*i=z;return 1;}size_t p;if(pp(d,n,&z,&p)){size_t need=(size_t)z.width*z.height*3u;if(need>cap)return 0;for(size_t k=0;k<need;k++)rgb[k]=d[p+k];if(i)*i=z;return 1;}return 0;}
